//! 📋️ Vector backing, one original field, one child and one new retained row advance on separate funded turns.
use super::*;
pub struct VectorReceiving<T:DslOwnedReceivingField>{source:OwnedSlot<FieldValue>,current:OwnedSlot<FieldValue>,child_output:OwnedSlot<T>,output:OwnedSlot<Vec<T>>,child:OwnedReceivingSlot<T>,index:usize,length:usize,phase:u8,closing:bool,failed:bool}
impl<T:DslOwnedReceivingField>Default for VectorReceiving<T>{fn default()->Self{Self{source:Default::default(),current:Default::default(),child_output:Default::default(),output:Default::default(),child:OwnedReceivingSlot::new(),index:0,length:0,phase:0,closing:false,failed:false}}}
impl<T:DslOwnedReceivingField>DslOwnedReceivingField for Vec<T>{type Cursor=VectorReceiving<T>;fn receiving_cursor()->Self::Cursor{Self::Cursor::default()}}
impl<T:DslOwnedReceivingField>VectorReceiving<T>{
 fn selected(&mut self,source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{if self.failed||self.closing{return RetainedWorkOutcome{result:Err(invariant().into()),work:0}}if self.phase==8{return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.demands(source,body){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}match self.phase{1 if self.output.value.is_none()=>return physical(native.admit_vec(&mut self.output.value,self.length,g)),3 if !self.child.is_ready()=>return self.child.step(&mut self.current.value,native,body,child_grant(g)),4 if self.child_output.value.is_none()=>return normal(self.child.take_into(&mut self.child_output.value,child_grant(g))),5 if !self.child.terminal_is_empty()=>return post_child_close(self.child.close_step(child_grant(g)),native,g),7 if !self.source.terminal_is_empty()=>return close_source(&mut self.source,native,g),_=>{}}if let Err(e)=native.checkpoint(){return RetainedWorkOutcome{result:Err(e.into()),work:0}}let result=(||{match self.phase{0=>{let value=source.as_ref().ok_or_else(invalid)?;self.length=match value{FieldValue::List(v)|FieldValue::Tuple(v)=>v.len(),FieldValue::Bytes64(v)=>v.len(),_=>return Err(invalid())};*self.source.value=source.take();self.phase=1;},1=>self.phase=2,2=>{if self.index==self.length{self.phase=7;}else{if !self.current.terminal_is_empty(){return Err(invariant())}let value=match self.source.value.as_mut().ok_or_else(invariant)?{FieldValue::List(v)|FieldValue::Tuple(v)=>std::mem::replace(v.get_mut(self.index).ok_or_else(invariant)?,FieldValue::Absent),FieldValue::Bytes64(v)=>FieldValue::UInt(u64::from(*v.retained_bytes().get(self.index).ok_or_else(invariant)?)),_=>return Err(invariant())};*self.current.value=Some(value);self.phase=3;}},3=>self.phase=4,4=>self.phase=5,5=>self.phase=6,6=>{let output=self.output.value.as_mut().ok_or_else(invariant)?;if output.len()==output.capacity()||self.child_output.value.is_none(){return Err(invariant())}output.push(self.child_output.value.take().unwrap());self.index+=1;self.child=OwnedReceivingSlot::new();self.phase=2;},7=>self.phase=8,_=>return Err(invariant())}Ok(receipt(d))})();RetainedWorkOutcome{result:result.map_err(|e|OriginalReceivingPrimary::from(e.with_retained_progress(receipt(metadata::<()>())))),work:1}}
}
impl<T:DslOwnedReceivingField>OwnedFieldReceiving<Vec<T>>for VectorReceiving<T>{
 fn demands(&self,_:&Option<FieldValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.failed||self.closing{return Err(invariant())}match self.phase{0=>Ok(metadata::<()>()),1 if self.output.value.is_none()=>Ok(RetirementDemand{capacity_bytes:self.length.checked_mul(std::mem::size_of::<T>()).ok_or_else(invariant)?,depth:1,..Default::default()}),2 if self.index<self.length&&matches!(self.source.value.as_ref(),Some(FieldValue::Bytes64(_)))=>Ok(payload::<u64>()),3 if !self.child.is_ready()=>self.child.demands(&self.current.value,body).and_then(nested),4 if self.child_output.value.is_none()=>nested(nested(metadata::<T>())?),5 if !self.child.terminal_is_empty()=>self.child.close_demands(body).and_then(nested),6=>Ok(payload::<T>()),7 if !self.source.terminal_is_empty()=>self.source.close_demands(body),8=>Ok(Default::default()),_=>Ok(metadata::<()>())}}
 fn step(&mut self,source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{let turn=self.selected(source,native,body,g);if turn.result.is_err()&&turn.work>0{self.failed=true}turn}
 fn is_ready(&self)->bool{!self.closing&&!self.failed&&self.phase==8&&self.output.value.is_some()}
 fn take_into(&mut self,output:&mut Option<Vec<T>>,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if !self.is_ready(){return RetainedWorkOutcome{result:Err(invariant()),work:0}}move_into(&mut self.output.value,output,g)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(metadata::<()>())}if !self.child.terminal_is_empty(){return self.child.close_demands(body).and_then(nested)}if !self.current.terminal_is_empty(){return self.current.close_demands(body)}if !self.child_output.terminal_is_empty(){return self.child_output.close_demands(body)}if !self.output.terminal_is_empty(){return self.output.close_demands(body)}self.source.close_demands(body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}if !self.closing{self.closing=true;return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if !self.child.terminal_is_empty(){return self.child.close_step(child_grant(g))}if !self.current.terminal_is_empty(){return self.current.close_step(g)}if !self.child_output.terminal_is_empty(){return self.child_output.close_step(g)}if !self.output.terminal_is_empty(){return self.output.close_step(g)}self.source.close_step(g)}
 fn terminal_is_empty(&self)->bool{self.child.terminal_is_empty()&&self.current.terminal_is_empty()&&self.child_output.terminal_is_empty()&&self.output.terminal_is_empty()&&self.source.terminal_is_empty()}
}
